// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 v1, uint256 v2) public {
        vm.assume(v1 != v2);

        // first call sets MinSum to v1
        c.SetMinSum(v1);
        assertEq(c.MinSum(), v1);

        // rule: while not Initialized(), SetMinSum can always be re-called and the LAST value wins
        bool ok;
        try c.SetMinSum(v2) { ok = true; } catch { ok = false; }

        assertTrue(ok && c.MinSum() == v2);
    }
}
